effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 uv = acScreenNorm;
  float t = acTime * speed;
  uv += vec2(sin(t) * 0.5 + sin(t * 1.7) * 0.5, cos(t * 1.3)) * weave;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  c *= mix(vec3(1.0), vec3(1.12, 0.98, 0.82), warmth);
  float n = gmHash(floor(uv * acScreenSize) + floor(acTime * 24.0)) - 0.5;
  c += n * grain * 0.35;
  float d = length((uv - 0.5) * vec2(1.4, 1.0));
  c *= 1.0 - vignette * smoothstep(0.25, 0.9, d);
  gl_FragColor = vec4(clamp(c, 0.0, 1.0) * a, a);
}
